  world.addBullet(shell(world));
  const beam = shell(world, {
    owner: owner.uid,
    enemy: true,
    kind: 'healBeam',
    damage: 1,
    radius: 0,
    symbol: 2015,
    healingTarget: patient,
    targetId: patient.uid,
    contactFrames: 10,
  });
