    laterBulletAge: sentinel.age,
    avatarAge: world.player.age,
    callbacks,
  };
  await draw(world, 4, 'Next frame: detach and live-array removal');
  stage.advance(20, 50);
  const recovered = { laterBulletAge: sentinel.age, avatarAge: world.player.age, callbacks };
